import unittest
from candidate import intersperse

class TestIntersperseFunction(unittest.TestCase):
    def test_intersperse_normal_multiple_elements(self):
        self.assertEqual(intersperse([1, 2, 3], 4), [1, 4, 2, 4, 3])

    def test_intersperse_single_element(self):
        self.assertEqual(intersperse([5], 4), [5])

    def test_intersperse_empty_list(self):
        self.assertEqual(intersperse([], 4), [])

    def test_intersperse_none_numbers_returns_empty(self):
        self.assertEqual(intersperse(None, 4), [])

    def test_intersperse_numbers_with_none_elements(self):
        self.assertEqual(intersperse([1, None, 3], 4), [1, 4, None, 4, 3])

    def test_intersperse_negative_delimiter(self):
        self.assertEqual(intersperse([1, 2], -3), [1, -3, 2])

    def test_intersperse_large_delimiter(self):
        large = 10**9
        self.assertEqual(intersperse([1, 2, 3], large), [1, large, 2, large, 3])

    def test_intersperse_non_int_delimiter_string(self):
        self.assertEqual(intersperse([1, 2], 'x'), [1, 'x', 2])

    def test_intersperse_non_int_delimiter_none(self):
        self.assertEqual(intersperse([1, 2], None), [1, None, 2])

    def test_intersperse_non_list_numbers_type_error(self):
        with self.assertRaises(TypeError):
            intersperse(5, 4)

    def test_intersperse_tuple_numbers(self):
        self.assertEqual(intersperse((1, 2, 3), 4), [1, 4, 2, 4, 3])

    def test_intersperse_original_list_unchanged(self):
        original = [1, 2, 3]
        intersperse(original, 4)
        self.assertEqual(original, [1, 2, 3])

    def test_intersperse_result_length_for_n_elements(self):
        for n in range(0, 6):
            numbers = list(range(n))
            result = intersperse(numbers, 0)
            expected_length = 0 if n == 0 else 2 * n - 1
            self.assertEqual(len(result), expected_length)

    def test_intersperse_negative_numbers(self):
        self.assertEqual(intersperse([-1, -2], -3), [-1, -3, -2])

    def test_intersperse_delimiter_as_list(self):
        self.assertEqual(intersperse([1, 2], [9]), [1, [9], 2])

    def test_intersperse_generator_raises_type_error(self):
        gen = (x for x in [1, 2, 3])
        with self.assertRaises(TypeError):
            intersperse(gen, 4)

if __name__ == '__main__':
    unittest.main()
